#include <iostream>
#include <memory>
#include <string>

// Minimal template node
template<typename T>
struct ListNode {
    T data;
    ListNode* nextPtr{nullptr};
    ListNode(const T& val) : data(val), nextPtr(nullptr) {}
};

// Minimal template list base
template<typename T>
class List {
protected:
    ListNode<T>* firstPtr{nullptr};
    ListNode<T>* lastPtr{nullptr};

public:
    List() = default;
    ~List() {
        while (!isEmpty()) {
            T temp;
            removeFromFront(temp);
        }
    }

    void insertAtBack(const T& val) {
        auto* newPtr = new ListNode<T>(val);
        if (isEmpty()) {
            firstPtr = lastPtr = newPtr;
        } else {
            lastPtr->nextPtr = newPtr;
            lastPtr = newPtr;
        }
    }

    bool removeFromFront(T& val) {
        if (isEmpty()) return false;
        ListNode<T>* tempPtr = firstPtr;
        val = firstPtr->data;
        firstPtr = firstPtr->nextPtr;
        if (firstPtr == nullptr) lastPtr = nullptr;
        delete tempPtr;
        return true;
    }

    bool isEmpty() const { return firstPtr == nullptr; }

    void print() const {
        if (isEmpty()) {
            std::cout << "The list is empty\n";
            return;
        }
        std::cout << "The list is:";
        ListNode<T>* current = firstPtr;
        while (current != nullptr) {
            std::cout << ' ' << current->data;
            current = current->nextPtr;
        }
        std::cout << '\n';
    }
};

// Queue class inheriting privately from List
template<typename QUEUETYPE>
class Queue : private List<QUEUETYPE> {
public:
    void enqueue(const QUEUETYPE& data) {
        this->insertAtBack(data);
    }

    bool dequeue(QUEUETYPE& data) {
        return this->removeFromFront(data);
    }

    bool isQueueEmpty() const {
        return this->isEmpty();
    }

    void printQueue() const {
        this->print();
    }
};

int main() {
    Queue<int> intQueue;
    std::cout << "processing an integer Queue\n";
    for (int i = 0; i < 3; ++i) {
        intQueue.enqueue(i);
        intQueue.printQueue();
    }

    int val;
    while (!intQueue.isQueueEmpty()) {
        intQueue.dequeue(val);
        std::cout << val << " dequeued\n";
        intQueue.printQueue();
    }

    return 0;
}

#include <iostream>
#include <vector>

// Minimal TreeNode structure
struct TreeNode {
    int data;
    TreeNode* leftPtr{nullptr};
    TreeNode* rightPtr{nullptr};
    TreeNode(int val) : data(val), leftPtr(nullptr), rightPtr(nullptr) {}
};

// Function to insert a node in a BST (no duplicates)
void insertNode(TreeNode*& nodePtr, int val) {
    if (nodePtr == nullptr) {
        nodePtr = new TreeNode(val);
    } else if (val < nodePtr->data) {
        insertNode(nodePtr->leftPtr, val);
    } else if (val > nodePtr->data) {
        insertNode(nodePtr->rightPtr, val);
    }
}

// Recursive traversals
void preOrder(const TreeNode* nodePtr) {
    if (nodePtr != nullptr) {
        std::cout << nodePtr->data << ' ';
        preOrder(nodePtr->leftPtr);
        preOrder(nodePtr->rightPtr);
    }
}

void inOrder(const TreeNode* nodePtr) {
    if (nodePtr != nullptr) {
        inOrder(nodePtr->leftPtr);
        std::cout << nodePtr->data << ' ';
        inOrder(nodePtr->rightPtr);
    }
}

void postOrder(const TreeNode* nodePtr) {
    if (nodePtr != nullptr) {
        postOrder(nodePtr->leftPtr);
        postOrder(nodePtr->rightPtr);
        std::cout << nodePtr->data << ' ';
    }
}

void destroyTree(TreeNode* nodePtr) {
    if (nodePtr != nullptr) {
        destroyTree(nodePtr->leftPtr);
        destroyTree(nodePtr->rightPtr);
        delete nodePtr;
    }
}

int main() {
    TreeNode* root = nullptr;
    // Values from textbook Fig 19.19 / Fig 19.20 sample
    std::vector<int> values = {47, 25, 77, 11, 43, 65, 31, 44, 68};
    for (int v : values) {
        insertNode(root, v);
    }

    std::cout << "Preorder traversal:\n";
    preOrder(root);
    std::cout << "\nInorder traversal:\n";
    inOrder(root);
    std::cout << "\nPostorder traversal:\n";
    postOrder(root);
    std::cout << '\n';

    destroyTree(root);
    return 0;
}
